public class Main {
    static int add(int a, int b) { return Math.addExact(a, b); }
    static void checkEquals(int expected, int actual, String label) {
        if (expected != actual) throw new AssertionError(label + ": expected " + expected + ", got " + actual);
    }
    public static void main(String[] args) {
        checkEquals(5, add(2, 3), "normal case");
        checkEquals(0, add(-2, 2), "boundary case");
        boolean overflowRejected = false;
        try { add(Integer.MAX_VALUE, 1); } catch (ArithmeticException expected) { overflowRejected = true; }
        if (!overflowRejected) throw new AssertionError("overflow should be rejected");
        System.out.println("All checks passed");
    }
}
